pub struct RuntimeState {
    /// 脚本执行位置
    pub position: ScriptPosition,

    /// 会话变量（游戏重启时清空）
    pub variables: HashMap<String, VarValue>,

    /// 持久变量（跨会话保留，key 为 bare key，不含 `persistent.` 前缀）
