    #[serde(default)]
    pub call_stack: Vec<ScriptPosition>,

    /// 当前等待状态
    pub waiting: WaitingReason,

    /// 当前显示的角色立绘
    /// Key: alias, Value: (path, position)
    pub visible_characters: HashMap<String, (String, crate::command::Position)>,

    /// 当前背景
    pub current_background: Option<String>,

    RequestUI {
        /// 请求标识符（用于匹配响应）
        key: String,
        /// UI 模式标识（Host 据此选择展示哪种 UI）
        mode: String,
        /// 模式特定参数
        params: HashMap<String, VarValue>,
    },
}

